function fetchCustomersByIds(ids){
  // ONE query: returns matching rows, but DB returns them sorted by id,
  // NOT in the order they were requested. Dedup happens here.
  const all = {3:{id:3,name:'Mara'}, 7:{id:7,name:'Sven'}};
  const unique = [...new Set(ids)].sort((a,b)=>a-b);
  return unique.map(id => all[id]);
}
function attachCustomers(orders){
  const ids = orders.map(o => o.customerId);
  const rows = fetchCustomersByIds(ids);
  return orders.map((o, i) => ({ orderId: o.orderId, customer: rows[i] }));
}

