// "Fixes" the N+1 on the orders list
async function withCustomers(orders) {
  const result = [];
  for (const order of orders) {
    const customer = await db.query(
      'SELECT * FROM customers WHERE id = $1', [order.customerId]
    );
    result.push({ ...order, customer: customer.rows[0] });
  }
  return result;
}
